class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        l = bad = ans = 0
        for r in range(len(s)):
            if r and s[r] == s[r-1]:
                bad += 1
            while bad > 1:
                if s[l] == s[l+1]:
                    bad -= 1
                l += 1
            ans = max(ans, r - l + 1)
        return ans

