class Solution {
public:
    int longestSemiRepetitiveSubstring(string s) {
        int l = 0, bad = 0, ans = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            if (r && s[r] == s[r-1]) bad++;
            while (bad > 1) {
                if (s[l] == s[l+1]) bad--;
                l++;
            }
            ans = max(ans, r - l + 1);
        }
        return ans;
    }
};

